cache = {}

for path, old_b64, new_b64, label in patches:
    target = Path(path)

    if not target.exists():
        raise SystemExit(
            f"Missing {path}"
        )

    text = cache.get(
        path,
        target.read_text(
            encoding="utf-8",
        ),
    )

    old = base64.b64decode(
        old_b64
    ).decode("utf-8")

    new = base64.b64decode(
        new_b64
    ).decode("utf-8")

    count = text.count(old)

    if count != 1:
        raise SystemExit(
            f"{label}: expected 1 match, found {count}."
        )

    cache[path] = text.replace(
        old,
        new,
        1,
    )

new_component = Path(
    "components/polls/polls-context-panel.tsx"
)

if new_component.exists():
    raise SystemExit(
        "components/polls/polls-context-panel.tsx already exists."
    )

new_component.parent.mkdir(
    parents=True,
    exist_ok=True,
)

new_component.write_text(
    base64.b64decode(
        ""
    ).decode("utf-8"),
    encoding="utf-8",
)

print("✓ created", new_component)

for path, text in cache.items():
    Path(path).write_text(
        text,
        encoding="utf-8",
    )
    print("✓", path)

